"""Deterministically split the byte-locked cert-manager static release.

This promotion tool never downloads content. It verifies the complete upstream
file before parsing, preserves stable upstream document order inside each phase,
and proves that the two generated inventories are disjoint and that their
normalized union is identical to all upstream Kubernetes objects.
"""

from __future__ import annotations

import argparse
import hashlib
import re
import subprocess
import tempfile
from pathlib import Path

DOCUMENT_SEPARATOR = re.compile(r"(?m)^---[ \t]*$")
TOP_LEVEL_API_VERSION = re.compile(r"(?m)^apiVersion:[ \t]*\S+[ \t]*$")
TOP_LEVEL_KIND = re.compile(r"(?m)^kind:[ \t]*(\S+)[ \t]*$")


def sha256_bytes(content: bytes) -> str:
    return hashlib.sha256(content).hexdigest()


def split_documents(source_text: str) -> tuple[str, list[str]]:
    first_api_version = TOP_LEVEL_API_VERSION.search(source_text)
    if first_api_version is None:
        raise ValueError("verified upstream source contains no Kubernetes object")
    source_header = source_text[: first_api_version.start()].rstrip()

    documents: list[str] = []
    for chunk in DOCUMENT_SEPARATOR.split(source_text):
        api_version = TOP_LEVEL_API_VERSION.search(chunk)
        kind = TOP_LEVEL_KIND.search(chunk)
        if api_version is None and kind is None:
            continue
        if api_version is None or kind is None:
            raise ValueError("upstream document has an incomplete apiVersion/kind identity")
        # Leading source-template comments are non-semantic. Start every generated
        # object at apiVersion so normalization is independent of comment placement.
        documents.append(chunk[api_version.start() :].strip())
    return source_header, documents


def render_phase(source_header: str, phase: str, documents: list[str]) -> bytes:
    generated_header = (
        "# yamllint disable-file\n"
        f"{source_header}\n\n"
        "# Generated by infra/gitops/vendor/cert-manager/split_release.py.\n"
        f"# Transactional phase: {phase}. Do not edit this generated upstream artifact.\n"
    )
    return (generated_header + "\n---\n".join(documents) + "\n").encode("utf-8")


def canonical_inventory(paths: list[Path]) -> bytes:
    expression = (
        "[.] | flatten | "
        "map(select(.kind != null and .apiVersion != null)) | "
        'sort_by(.apiVersion, .kind, (.metadata.namespace // ""), .metadata.name)'
    )
    result = subprocess.run(
        ["yq", "eval-all", "-o=json", "-I=0", expression, *map(str, paths)],
        check=True,
        stdout=subprocess.PIPE,
    )
    return result.stdout


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--source", required=True, type=Path)
    parser.add_argument("--expected-sha256", required=True)
    parser.add_argument("--expected-bytes", required=True, type=int)
    parser.add_argument("--expected-objects", default=49, type=int)
    parser.add_argument("--expected-crds", default=6, type=int)
    parser.add_argument("--crds-output", required=True, type=Path)
    parser.add_argument("--controllers-output", required=True, type=Path)
    parser.add_argument(
        "--check",
        action="store_true",
        help="compare generated bytes with existing outputs instead of rewriting them",
    )
    return parser.parse_args()


def main() -> None:
    args = parse_args()
    source_bytes = args.source.read_bytes()
    if len(source_bytes) != args.expected_bytes:
        raise ValueError(
            f"upstream byte-count mismatch: expected {args.expected_bytes}, got {len(source_bytes)}"
        )
    actual_sha = sha256_bytes(source_bytes)
    if actual_sha != args.expected_sha256:
        raise ValueError(
            f"upstream SHA-256 mismatch: expected {args.expected_sha256}, got {actual_sha}"
        )

    source_header, documents = split_documents(source_bytes.decode("utf-8"))
    if len(documents) != args.expected_objects:
        raise ValueError(
            f"upstream object-count mismatch: expected {args.expected_objects}, got {len(documents)}"
        )
    crds = [
        document
        for document in documents
        if TOP_LEVEL_KIND.search(document).group(1) == "CustomResourceDefinition"
    ]
    controllers = [
        document
        for document in documents
        if TOP_LEVEL_KIND.search(document).group(1) != "CustomResourceDefinition"
    ]
    if len(crds) != args.expected_crds:
        raise ValueError(
            f"upstream CRD-count mismatch: expected {args.expected_crds}, got {len(crds)}"
        )
    if set(crds).intersection(controllers):
        raise ValueError("CRD and controller phases are not disjoint")

    crd_bytes = render_phase(source_header, "crds", crds)
    controller_bytes = render_phase(source_header, "controllers", controllers)
    generated = (
        (args.crds_output, crd_bytes),
        (args.controllers_output, controller_bytes),
    )
    if args.check:
        for output_path, expected_content in generated:
            if not output_path.is_file() or output_path.read_bytes() != expected_content:
                raise ValueError(f"generated split drifted: {output_path}")
    else:
        for output_path, content in generated:
            output_path.parent.mkdir(parents=True, exist_ok=True)
            output_path.write_bytes(content)

    with tempfile.TemporaryDirectory(prefix="mindclade-cert-manager-split-") as temp_dir:
        normalized_source = canonical_inventory([args.source])
        normalized_union = canonical_inventory([args.crds_output, args.controllers_output])
        if normalized_union != normalized_source:
            mismatch_dir = Path(temp_dir)
            (mismatch_dir / "source.json").write_bytes(normalized_source)
            (mismatch_dir / "union.json").write_bytes(normalized_union)
            raise ValueError("normalized split union does not equal the upstream inventory")

    print(f"upstream.objects={len(documents)}")
    print(f"upstream.normalized-sha256={sha256_bytes(normalized_source)}")
    print(f"crds.objects={len(crds)}")
    print(f"crds.bytes={len(crd_bytes)}")
    print(f"crds.sha256={sha256_bytes(crd_bytes)}")
    print(f"controllers.objects={len(controllers)}")
    print(f"controllers.bytes={len(controller_bytes)}")
    print(f"controllers.sha256={sha256_bytes(controller_bytes)}")


if __name__ == "__main__":
    main()
